mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("push4 push7 push2 delete2 min","4"),
        ("push5 push1 delete1 min","5"),
        ("push1 push1 delete1 min","1"),
        ("push9 push3 push5 delete3 min","5"),
        ("push4 push2 delete4 min","2"),
        ("  \npush4 push7 push2 delete2 min\n  ","4"),
        ("\npush4 push2 delete4 min\n","2")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS lazy-heap-deletion");
}
